import numpy as np


def moving_average(data, window_size):
    """Calculate moving average with a given window size."""
    ma = []
    for i in range(len(data)):
        if i < window_size - 1:
            ma.append(np.mean(data[:i + 1]))
        else:
            ma.append(np.mean(data[i - window_size + 1:i + 1]))
    return ma


def exponential_moving_average(data, window_size):
    """Calculate Exponential Moving Average (EMA) with a given window size."""
    alpha = 2 / (window_size + 1)
    ema = [data[0]]

    for i in range(1, len(data)):
        ema.append(alpha * data[i] + (1 - alpha) * ema[i - 1])

    return ema


def simple_moving_average(data, window_size):
    """Calculate Simple Moving Average (SMA) with a given window size."""
    sma = []
    for i in range(len(data)):
        if i < window_size - 1:
            sma.append(np.mean(data[:i + 1]))
        else:
            sma.append(np.mean(data[i - window_size + 1:i + 1]))
    return sma


def median_moving_average(data, window_size):
    """Calculate Median Moving Average (MMA) with a given window size."""
    mma = []
    for i in range(len(data)):
        if i < window_size - 1:
            window_data = data[:i + 1]
        else:
            window_data = data[i - window_size + 1:i + 1]

        mma.append(np.median(window_data))
    return mma


def robust_moving_average(data, window_size, trim_fraction=0.1):
    """Calculate Robust Moving Average (RMA) with trimming."""
    rma = []
    trim_count = int(window_size * trim_fraction)

    for i in range(len(data)):
        if i < window_size - 1:
            window_data = data[:i + 1]
        else:
            window_data = data[i - window_size + 1:i + 1]

        sorted_window = np.sort(window_data)
        if len(sorted_window) > 2 * trim_count:
            trimmed_window = sorted_window[trim_count: -trim_count]
        else:
            trimmed_window = sorted_window

        rma.append(np.mean(trimmed_window))

    return rma


def winsorized_moving_average(data, window_size, winsorize_fraction=0.1):
    """Calculate Winsorized Moving Average (WMA) with a given window size."""
    wma = []
    winsorize_count = int(window_size * winsorize_fraction)
    for i in range(len(data)):
        if i < window_size - 1:
            window_data = data[:i + 1]
        else:
            window_data = data[i - window_size + 1:i + 1]

        sorted_window = np.sort(window_data)
        lower_bound = sorted_window[winsorize_count]
        upper_bound = sorted_window[-winsorize_count - 1]
        winsorized_window = np.clip(window_data, lower_bound, upper_bound)

        wma.append(np.mean(winsorized_window))
    return wma


def weighted_moving_average(data, window_size, weights=None):
    """Calculate Weighted Moving Average (WMA) with a given window size and weights."""
    wma = []
    if weights is None:
        weights = np.ones(window_size)
    else:
        weights = np.array(weights)

    weights = weights / weights.sum()

    for i in range(len(data)):
        if i < window_size - 1:
            window_data = data[:i + 1]
            window_weights = weights[:len(window_data)]
        else:
            window_data = data[i - window_size + 1:i + 1]
            window_weights = weights

        wma.append(np.dot(window_data, window_weights))

    return wma

